"item_number":80,"source_pages":[21],"answer_in_official_document":"E","answer_key_requires_clarification":false,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"parecer_individual_de_continuacao_com_publicacao_retida","reviewed_at":"2026-10-23T00:46:40.973169Z","publication_approved":false,"answer_verified":false,"historical_answer_letter_checked":true,"historical_answer_letter":"E","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/d18006a6f5222cffb59162f3eef346be0b410cef6bae2b059a27eb097032d1ee","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Órgão e pessoa jurídica","observed_style":"conceito_com_alternativas","explanation":"A Presidência integra a estrutura da Administração Direta e não é pessoa jurídica autônoma. E trata de órgão; a representação e competências específicas não se confundem com personalidade.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto","doutrina_pendente"],"primary_evidence":[{"reference":"cf:76","title":"Constituição Federal","url":"https://www2.camara.leg.br/legin/fed/consti/1988/constituicao-1988-5-outubro-1988-322142-normaatualizada-pl.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"a8de1643589cf9fb199bb58a0cf4a6acd63c35ed377843d8240ca500b7e1f2c1","excerpt_sha256":"f0a0fe90d1d5b04540107560083c78f0f7132d1e9847a647aeb11f5acc6961cb","excerpt_artifact":"fontes-e-excertos.json#/sources/c