36/idecan-2021-pc-ce-escrivao-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"a835d92983601375c77355a50f68bdc77092e4fb88fdb9686ff453b8ed2fd57d","source_pages":[25]},"target_scope":"historico_ce","pcac_compatibility_verified":false,"state_law_currentness_verified":false}}},{"candidate":"98507413dc622ea7e8a2f79ef9f93f6169689f910593d2b6c9eeee98f752279b","expected_status":"under_review","expected_payload":{"raw_text":"100. Com base na Lei 12.124/93 e suas atualizações posteriores,\nanalise as afirmativas a seguir:\nI. Os cargos de provimento em comissão da estrutura\norganizacional da Polícia Civil, diretamente envolvidos com a\natividade fim desta, serão preenchidos por policiais civis,\nintegrantes do Grupo Ocupacional Atividade de Polícia\nJudiciária-APJ, observada a formação profissional exigida para\no desempenho do cargo.\nII. Não haverá posse nos casos de ascensão funcional e\nreintegração.\nIII. No caso de disponibilidade, o servidor continuará sendo\nconsiderado como em atividade, computando-se o período de\nsuspensão\ndo\nvínculo\npara\na\naposentadoria,\nnova\ndisponibilidade, se for o caso, e a progressão horizontal.\nAssinale\nA) se apenas as afirmativas I e II estiverem corretas.\nB) se apenas as afirmativas I e III estiverem corretas.\nC) se apenas as afirmativas II e III estiverem corretas.\nD) se todas as afirmativas estiverem corretas.\nE) se nenhuma afirmativa estiver correta","item_number":100,"source_pages":[25],"answer_in_official_document":"C","answer_key_requires_clarification":false,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":true,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"100. Com base na Lei 12.124/93 e suas atualizações posteriores,\nanalise as afirmativas a seguir:\nI. Os cargos de provimento em comissão da estrutura\norganizacional da Polícia Civil, diretamente envolvidos com a\natividade fim desta, serão preenchidos por policiais civis,\nintegrantes do Grupo Ocupacional Atividade de Polícia\nJudiciária-APJ, observada a formação profissional exigida para\no desempenho do cargo.\nII. Não haverá posse nos casos de ascensão funcional e\nreintegração.\nIII. No caso de disponibilidade, o servidor continuará sendo\nconsiderado como em atividade, computando-se o período de\nsuspensão\ndo\nvínculo\npara\na\naposentadoria,\nnova\ndisponibilidade, se for o caso, e a progressão horizontal.\nAssinale\nA) se apenas as afirmativas I e II estiverem corretas.\nB) se apenas as afirmativas I e III estiverem corretas.\nC) se apenas as afirmativas II e III estiverem corretas.\nD) se todas as afirmativas estiverem corretas.\nE) se nenhuma afirmativa estiver correta","item_number":100,"source_pages":[25],"answer_in_official_document":"C","answer_key_requires_clarification":false,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":true,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"parecer_individual_de_continuacao_com_publicacao_retida","reviewed_at":"2026-10-23T00:46:40.973169Z","publication_approved":false,"answer_verified":false,"historical_answer_letter_checked":true,"historical_answer_letter":"C","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/98507413dc622ea7e8a2f79ef9f93f6169689f910593d2b6c9eeee98f752279b","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Estatuto da Polícia Civil cearense","observed_style":"lei_estadual_historica","explanation":"Posse, disponibilidade e preenchimento de comissão são regras da carreira cearense. O gabarito C fica histórico e pendente da fonte estadual, sem conversão em regra nacional ou acreana.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto","fonte_estadual_pendente","escopo_historico_ce","pertinencia_pcac_nao_comprovada"],"primary_evidence":[],"answer_key_evidence":{"url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","page":1,"checked_at":"2026-10-23T00:46:40.971776+00:00","section_heading_ambiguous":false,"scope":"Letra transcrita conferida no documento; isso não certifica a validade jurídica atual."},"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83736/idecan-2021-pc-ce-escrivao-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"a835d92983601375c77355a50f68bdc77092e4fb88fdb9686ff453b8ed2fd57d","source_pages":[25]},"target_scope":"historico_ce","pcac_compatibility_verified":false,"state_law_currentness_verified":false}}}]$idecan_review_batch$::jsonb) loop
    select * into stored from public.question_corpus_candidates where id=change->>'candidate' for update;
    if not found then raise exception 'Candidato não encontrado; aplique antes o acervo de 200 itens'; end if;
    if stored.content_status=change->>'next_status' and stored.payload=change->'next_payload' then continue; end if;
    if stored.content_status is distinct from change->>'expected_status'
      or stored.payload is distinct from change->'expected_payload' then
      raise exception 'Revisão desatualizada: decisão existente preservada; recarregue o candidato';
    end if;
    if stored.content_status <> 'under_review' then raise exception 'Decisão anterior protegida'; end if;
    if change->'next_payload'->'raw_text' is distinct from stored.payload->'raw_text' then
      raise exception 'Extração original protegida';
    end if;
    if change->'next_payload' ? 'publication'
      or change#>>'{next_payload,individual_review,publication_approved}' is distinct from 'false' then
      raise exception 'Este lote não permite publicação';
    end if;
    insert into public.question_corpus_review_audit(candidate_id,previous_status,next_status,previous_payload,next_payload,reviewer_id)
    values(stored.id,stored.content_status,change->>'next_status',stored.payload,change->'next_payload',auth.uid());
    update public.question_corpus_candidates set content_status=change->>'next_status',payload=change->'next_payload' where id=stored.id;
  end loop;
end $review$;
commit;
